-- Ecuador's government contracts -- 133K records of who bought what, from which company, for how much.
-- Auto-generated by scripts/gen_evidence_pages.py: 132,995 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("RECORD_DATE") as year, count(*) as records
from THE_LIBRARY.PROCUREMENT.ECUADOR_GOV_CONTRACTS
where "RECORD_DATE" is not null
group by 1
order by 1
